-- Preserve the original human-event proof; add only truthful NULL-actor system ownership evidence.
-- No money, publication, triage, promise or case-identity mutation is authorized by this branch.
DROP TRIGGER product_priority_case_revision;
--> statement-breakpoint
CREATE TRIGGER product_priority_case_revision BEFORE UPDATE ON product_priority_cases WHEN OLD.state='resolved' OR NEW.id<>OLD.id OR NEW.product_id<>OLD.product_id OR NEW.kind<>OLD.kind OR NEW.public_version_id IS NOT OLD.public_version_id OR NEW.reported_by<>OLD.reported_by OR NEW.created_at<>OLD.created_at OR NEW.revision<>OLD.revision+1 OR NOT (EXISTS(SELECT 1 FROM product_priority_events e JOIN review_tasks t ON t.source_type='product_priority' AND t.source_id=NEW.id AND t.source_revision=NEW.id WHERE e.id=NEW.last_event_id AND e.case_id=NEW.id AND e.product_id=NEW.product_id AND e.revision=NEW.revision AND json_extract(e.detail_json,'$.state')=NEW.state AND json_extract(e.detail_json,'$.backupId') IS NEW.backup_id AND json_extract(e.detail_json,'$.backupUnavailableReason')=NEW.backup_unavailable_reason AND json_extract(e.detail_json,'$.nextUpdateAt') IS NEW.next_update_at AND json_extract(e.detail_json,'$.ownerId') IS t.owner_id) OR EXISTS(SELECT 1 FROM audit_logs a JOIN review_tasks t ON t.id=a.subject_id AND t.source_type='product_priority' AND t.source_id=NEW.id AND t.source_revision=NEW.id WHERE a.actor_id IS NULL AND a.action='review_task.coverage_rerouted' AND a.subject_type='review_task' AND json_extract(a.command_result_json,'$.system')=1 AND json_type(a.command_result_json,'$.system')='true' AND json_extract(a.command_result_json,'$.sourceType')='product_priority' AND json_extract(a.command_result_json,'$.sourceId')=NEW.id AND json_extract(a.command_result_json,'$.sourceRevision')=NEW.id AND json_extract(a.command_result_json,'$.taskId')=t.id AND json_extract(a.command_result_json,'$.revision')=t.revision AND json_extract(a.command_result_json,'$.ownerId') IS t.owner_id AND json_extract(a.command_result_json,'$.nativePriority.id')=NEW.id AND json_extract(a.command_result_json,'$.nativePriority.productId')=NEW.product_id AND json_extract(a.command_result_json,'$.nativePriority.previousRevision')=OLD.revision AND json_extract(a.command_result_json,'$.nativePriority.revision')=NEW.revision AND json_extract(a.command_result_json,'$.nativePriority.lastHumanEventId')=OLD.last_event_id AND NEW.last_event_id=OLD.last_event_id AND NEW.state=OLD.state AND NEW.triaged_at IS OLD.triaged_at AND NEW.next_update_at IS OLD.next_update_at AND json_extract(a.command_result_json,'$.nativePriority.state')=NEW.state AND json_extract(a.command_result_json,'$.nativePriority.triagedAt') IS NEW.triaged_at AND json_extract(a.command_result_json,'$.nativePriority.nextUpdateAt') IS NEW.next_update_at AND json_extract(a.command_result_json,'$.nativePriority.backupId') IS NEW.backup_id AND json_extract(a.command_result_json,'$.nativePriority.backupUnavailableReason')=NEW.backup_unavailable_reason)) BEGIN SELECT RAISE(ABORT,'product_priority_case_revision'); END;
