CREATE TRIGGER review_task_system_ownership_receipt_immutable BEFORE UPDATE ON audit_logs WHEN OLD.action='review_task.coverage_rerouted' AND (NEW.id IS NOT OLD.id OR NEW.actor_id IS NOT OLD.actor_id OR NEW.action IS NOT OLD.action OR NEW.subject_type IS NOT OLD.subject_type OR NEW.subject_id IS NOT OLD.subject_id OR NEW.request_id IS NOT OLD.request_id OR NEW.created_at IS NOT OLD.created_at OR NEW.command_key IS NOT OLD.command_key OR NEW.command_digest IS NOT OLD.command_digest OR NEW.command_result_json IS NOT OLD.command_result_json) BEGIN SELECT RAISE(ABORT,'review_task_system_ownership_receipt_immutable'); END;
--> statement-breakpoint
CREATE TRIGGER review_task_system_ownership_receipt_retained BEFORE DELETE ON audit_logs WHEN OLD.action='review_task.coverage_rerouted' BEGIN SELECT RAISE(ABORT,'review_task_system_ownership_receipt_retained'); END;
